contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try to set approval for a target logger to a desired boolean status.
    // We assert that if the call does not revert then approvedToLog(target) equals status,
    // and if it reverts then approvedToLog(target) remains equal to its prior value.
    function run(address target, bool status) public payable {
        require(target != address(0));

        // read before value via public getter
        bool before = c.approvedToLog(target); if (__ESBMC_reverted()) return;

        bool reverted;
        // calling setApprovedLogger may revert (onlyOwner), capture whether it reverted
        c.setApprovedLogger(target, status); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool afterVal = c.approvedToLog(target); if (__ESBMC_reverted()) return;

        // General rule: either the call reverted and approval is unchanged, or it succeeded and approval equals status
        assert((reverted && afterVal == before) || (!reverted && afterVal == status));
    }

    receive() external payable { }
}

